import { Ionicons } from '@expo/vector-icons';
import {
  useFocusEffect,
  useNavigation,
  type NavigationProp,
  type ParamListBase,
} from '@react-navigation/native';
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  ActivityIndicator,
  type LayoutChangeEvent,
  RefreshControl,
  ScrollView,
  StyleSheet,
  Text,
  TextStyle,
  TouchableOpacity,
  View,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useSelector } from 'react-redux';
import familiesAPI from '../../api/families';
import groupsAPI from '../../api/groups';
import networkInvitesAPI from '../../api/networkInvites';
import type { GroupPartyUnit, GroupPlan } from '../../api/schemas';
import GroupSwitcher from '../family/GroupSwitcher';
import { useTheme } from '../../hooks/useTheme';
import {
  selectCurrentFamily,
  selectCurrentGroup,
  selectFamilies,
  selectInvitations,
} from '../../store/slices/familySlice';
import { haptics } from '../../utils/haptics';
import { getCollaborationConfig } from './collaborationConfig';
import type { CollaborationGroupKind, CollaborationMilestone } from './collaborationConfig';
import { takePendingWorkspaceMilestone } from './workspaceMilestones';
import { resolveWorkspaceSetupState } from './workspaceSetupState';

type ConnectedFamily = {
  id: string;
  name: string;
  memberCount?: number;
};

const statusTone = {
  DRAFT: { background: '#E5E7EB', color: '#4B5563' },
  OPEN: { background: '#DBEAFE', color: '#1D4ED8' },
  FINALIZED: { background: '#DCFCE7', color: '#15803D' },
  CANCELLED: { background: '#FEE2E2', color: '#B91C1C' },
} as const;

const templateLabel = {
  TEAM_SOCIAL: 'Team social',
  DINNER: 'Dinner',
  HANGOUT: 'Hangout',
  OTHER: 'Other',
} as const;
const PLANS_SECTION_SCROLL_OFFSET = 16;
const PLANS_SECTION_HIGHLIGHT_DURATION_MS = 1800;

const getPlanCardMeta = (plan: GroupPlan): string[] => {
  if (plan.mode !== 'LEGACY_SEPARATE' && plan.plan_options.length > 0) {
    const responderCount = new Set(
      (plan.option_responses ?? []).map((response) => response.response_unit.id)
    ).size;

    return [
      templateLabel[plan.template],
      `${plan.plan_options.length} ${plan.mode === 'TIME_ONLY' ? 'time options' : 'linked options'}`,
      responderCount > 0
        ? `${responderCount} ${responderCount === 1 ? 'responder' : 'responders'}`
        : 'Awaiting responses',
    ];
  }

  return [
    templateLabel[plan.template],
    `${plan.time_options.length} time options`,
    `${plan.choice_options.length} choices`,
  ];
};

const CollaborationWorkspaceRouter: React.FC = () => {
  const theme = useTheme();
  const navigation = useNavigation<NavigationProp<ParamListBase>>();
  const currentGroup = useSelector(selectCurrentGroup);
  const currentFamily = useSelector(selectCurrentFamily);
  const families = useSelector(selectFamilies);
  const invitations = useSelector(selectInvitations);
  const familyPlannerAgentEnabled = useSelector(
    (state: {
      profile?: {
        featureFlags?: {
          familyPlannerAgentEnabled?: boolean;
        };
      };
    }) => state.profile?.featureFlags?.familyPlannerAgentEnabled ?? false
  );
  const config = getCollaborationConfig(currentGroup?.groupKind);
  const [plans, setPlans] = useState<GroupPlan[]>([]);
  const [partyUnits, setPartyUnits] = useState<GroupPartyUnit[]>([]);
  const [connectedFamilies, setConnectedFamilies] = useState<ConnectedFamily[]>([]);
  const [pendingNetworkRequestCount, setPendingNetworkRequestCount] = useState(0);
  const [activeMilestone, setActiveMilestone] = useState<CollaborationMilestone | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isPlansSectionHighlighted, setIsPlansSectionHighlighted] = useState(false);
  const [plansSectionY, setPlansSectionY] = useState<number | null>(null);

