111	  const scrollViewRef = useRef<ScrollView | null>(null);
112	  const plansSectionHighlightTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
113	  const latestRequestIdRef = useRef(0);
114	  const latestGroupIdRef = useRef<string | null>(currentGroup?.id ?? null);
115	
116	  const clearPlansSectionHighlightTimeout = useCallback(() => {
117	    if (plansSectionHighlightTimeoutRef.current) {
118	      clearTimeout(plansSectionHighlightTimeoutRef.current);
119	      plansSectionHighlightTimeoutRef.current = null;
120	    }
121	  }, []);
122	
123	  useEffect(() => {
124	    latestGroupIdRef.current = currentGroup?.id ?? null;
125	  }, [currentGroup?.id]);
126	
127	  useEffect(() => {
128	    clearPlansSectionHighlightTimeout();
129	    setIsPlansSectionHighlighted(false);
130	    setPlansSectionY(null);
131	  }, [clearPlansSectionHighlightTimeout, currentGroup?.id]);
132	
133	  useEffect(
134	    () => () => {
135	      clearPlansSectionHighlightTimeout();
136	      latestRequestIdRef.current += 1;
137	    },
138	    [clearPlansSectionHighlightTimeout]
139	  );
140	
141	  const loadWorkspace = useCallback(
142	    async (refresh = false) => {
143	      const groupId = currentGroup?.id ?? null;
144	      const groupKind = currentGroup?.groupKind;
145	      const requestId = latestRequestIdRef.current + 1;
146	      latestRequestIdRef.current = requestId;
147	
148	      if (!groupId || !config) {
149	        setPlans([]);
150	        setPartyUnits([]);
151	        setConnectedFamilies([]);
152	        setPendingNetworkRequestCount(0);
153	        setIsLoading(false);
154	        setIsRefreshing(false);
155	        setError(null);
156	        return;
157	      }
158	
159	      if (refresh) {
160	        setIsRefreshing(true);
161	      } else {
162	        setIsLoading(true);
163	      }
164	
165	      try {
166	        let nextPlans: GroupPlan[] = [];
167	        let nextPartyUnits: GroupPartyUnit[] = [];
168	        let nextConnectedFamilies: ConnectedFamily[] = [];
169	
170	        if (groupKind === 'META') {
