const [plansSectionY, setPlansSectionY] = useState<number | null>(null);
const scrollViewRef = useRef<ScrollView | null>(null);
const plansSectionHighlightTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
const latestRequestIdRef = useRef(0);
const latestGroupIdRef = useRef<string | null>(currentGroup?.id ?? null);

const clearPlansSectionHighlightTimeout = useCallback(() => {
  if (plansSectionHighlightTimeoutRef.current) {
    clearTimeout(plansSectionHighlightTimeoutRef.current);
    plansSectionHighlightTimeoutRef.current = null;
  }
}, []);

useEffect(() => {
  latestGroupIdRef.current = currentGroup?.id ?? null;
}, [currentGroup?.id]);

useEffect(() => {
  clearPlansSectionHighlightTimeout();
  setIsPlansSectionHighlighted(false);
  setPlansSectionY(null);
}, [clearPlansSectionHighlightTimeout, currentGroup?.id]);

useEffect(
  () => () => {
    clearPlansSectionHighlightTimeout();
    latestRequestIdRef.current += 1;
  },
  [clearPlansSectionHighlightTimeout]
);

const loadWorkspace = useCallback(
  async (refresh = false) => {
    const groupId = currentGroup?.id ?? null;
    const groupKind = currentGroup?.groupKind;
    const requestId = latestRequestIdRef.current + 1;
    latestRequestIdRef.current = requestId;

    if (!groupId || !config) {
      setPlans([]);
      setPartyUnits([]);
      setConnectedFamilies([]);
      setPendingNetworkRequestCount(0);
      setIsLoading(false);
      setIsRefreshing(false);
      setError(null);
      return;
    }

    if (refresh) {
      setIsRefreshing(true);
    } else {
      setIsLoading(true);
    }

    try {
      let nextPlans: GroupPlan[] = [];
      let nextPartyUnits: GroupPartyUnit[] = [];
      let nextConnectedFamilies: ConnectedFamily[] = [];

      if (groupKind === 'META') {
        const [plansPayload, memberships, incomingInvites, adminInvites] = await Promise.all([
          groupsAPI.getPlans(groupId),
          familiesAPI.getMetaMemberships(),
          networkInvitesAPI.list({ scope: 'incoming' }),
          networkInvitesAPI.list({ scope: 'admin' }),
        ]);
        nextPlans = plansPayload;
        const homeFamilyId = currentFamily?.id ? String(currentFamily.id) : null;
        nextConnectedFamilies = memberships
          .filter((membership) => String(membership.meta_family?.id) === groupId)
          .map((membership) => membership.family)
          .filter(Boolean)
          .filter((family) => String(family.id) !== homeFamilyId)
          .map((family) => ({
            id: String(family.id),
            name: family.name,
            memberCount: family.members?.length,
          }))
          .sort((a, b) => a.name.localeCompare(b.name));
        setPendingNetworkRequestCount(
          [...incomingInvites, ...adminInvites].filter(
            (invite) => String(invite.meta_family?.id ?? '') === groupId
          ).length
        );
      } else {
        const [plansPayload, partyUnitsPayload] = await Promise.all([
          groupsAPI.getPlans(groupId),
          groupsAPI.getPartyUnits(groupId),
        ]);
        nextPlans = plansPayload;
        nextPartyUnits = partyUnitsPayload;
        setPendingNetworkRequestCount(0);
      }

      if (latestRequestIdRef.current !== requestId || latestGroupIdRef.current !== groupId) {
        return;
      }

      setPlans(nextPlans);
      setPartyUnits(nextPartyUnits);
      setConnectedFamilies(nextConnectedFamilies);
      setError(null);
    } catch (loadError) {
      if (latestRequestIdRef.current !== requestId || latestGroupIdRef.current !== groupId) {
        return;
      }
      console.error('Failed to load collaboration workspace:', loadError);
      setError('Failed to load collaboration plans.');
    } finally {
      if (latestRequestIdRef.current === requestId && latestGroupIdRef.current === groupId) {
        setIsLoading(false);
        setIsRefreshing(false);
      }
    }
  },
  [config, currentFamily?.id, currentGroup?.groupKind, currentGroup?.id]
);

useFocusEffect(
  useCallback(() => {
    let isFocused = true;

    const hydrateWorkspace = async () => {
      await loadWorkspace();
      if (!isFocused || !currentGroup?.id) {
        return;
      }

      const nextMilestone = takePendingWorkspaceMilestone(currentGroup.id);
      setActiveMilestone(nextMilestone);
      if (nextMilestone) {
        haptics.success();
      }
    };

    void hydrateWorkspace();

    return () => {
      isFocused = false;
      setActiveMilestone(null);
    };
  }, [currentGroup?.id, loadWorkspace])
);

const responseUnitCount = useMemo(() => {
  if (currentGroup?.groupKind === 'META') {
    return connectedFamilies.length;
  }
  return partyUnits.length;
}, [connectedFamilies.length, currentGroup?.groupKind, partyUnits.length]);

const handlePlansSectionLayout = useCallback((event: LayoutChangeEvent) => {
  setPlansSectionY(event.nativeEvent.layout.y);
}, []);

const highlightPlansSection = useCallback(() => {
  clearPlansSectionHighlightTimeout();
  setIsPlansSectionHighlighted(true);
  plansSectionHighlightTimeoutRef.current = setTimeout(() => {
    setIsPlansSectionHighlighted(false);
    plansSectionHighlightTimeoutRef.current = null;
  }, PLANS_SECTION_HIGHLIGHT_DURATION_MS);
}, [clearPlansSectionHighlightTimeout]);

const handleJumpToPlans = useCallback(() => {
  if (plansSectionY == null) {
    return;
  }

  scrollViewRef.current?.scrollTo({
    y: Math.max(0, plansSectionY - PLANS_SECTION_SCROLL_OFFSET),
    animated: true,
  });
  highlightPlansSection();
}, [highlightPlansSection, plansSectionY]);

const openPlansCount = plans.filter((plan) => plan.status === 'OPEN').length;
const plannerHostFamily = useMemo(() => {
  if (currentFamily?.isHomeGroup) {
    return currentFamily;
  }

  return families.find((family) => family.isHomeGroup) ?? currentFamily;
}, [currentFamily, families]);
const plannerEnabled =
  currentGroup?.groupKind === 'META' &&
  familyPlannerAgentEnabled &&
  plannerHostFamily?.featureSettings?.agent_enabled === true;
const pendingInvitationCount =
  currentGroup?.groupKind === 'META'
    ? pendingNetworkRequestCount
    : invitations.filter(
        (invitation) =>
          invitation.familyId === currentGroup?.id &&
          invitation.status.toLowerCase() === 'pending'
      ).length;
const setupState =
  currentGroup && config
    ? resolveWorkspaceSetupState({
        groupKind: currentGroup.groupKind as CollaborationGroupKind,
        memberCount: currentGroup.memberCount,
        pendingInviteCount: pendingInvitationCount,
        responseUnitCount,
        planCount: plans.length,
      })
    : null;
const setupStep =
  setupState && setupState !== 'ready' && config ? config.setupSteps[setupState] : null;
const activeMilestoneMessage =
  activeMilestone && config ? (config.milestoneMessages[activeMilestone] ?? null) : null;

const handleSetupAction = useCallback(() => {
  if (!setupStep || !currentGroup || !setupState) {
    return;
  }

  if (currentGroup.groupKind === 'META') {
    if (setupState === 'configured') {
      navigation.navigate('Trips', {
        screen: 'CreateTrip',
        params: {
          networkId: currentGroup.id,
          returnTo: 'detail',
        },
      });
      return;
    }

    navigation.navigate('InvitationScreen', {
      groupId: currentGroup.id,
    });
    return;
  }

  if (setupState === 'empty') {
    navigation.navigate('InvitationScreen', {
      groupId: currentGroup.id,
    });
    return;
  }

  if (setupState === 'invited') {
    navigation.navigate('GroupParticipants', {
      groupId: currentGroup.id,
    });
    return;
  }

  navigation.navigate('GroupPlanComposer', {
    groupId: currentGroup.id,
  });
}, [currentGroup, navigation, setupState, setupStep]);

if (!currentGroup || !config) {
  return null;
}

if (isLoading && !isRefreshing) {
  return (
    <SafeAreaView style={styles.loadingContainer}>
      <ActivityIndicator size="large" color={theme.colors.primary[400]} />
      <Text style={[styles.loadingText, { color: theme.colors.text.secondary }]}>
        Loading collaboration workspace...
      </Text>
    </SafeAreaView>
  );
}

return (
  <SafeAreaView
    style={[styles.container, { backgroundColor: theme.colors.background.paper }]}
    testID="collaboration-workspace-screen"
  >
    <ScrollView
      ref={scrollViewRef}
      testID="collaboration-workspace-scroll"
      contentContainerStyle={styles.scrollContent}
      refreshControl={
        <RefreshControl refreshing={isRefreshing} onRefresh={() => void loadWorkspace(true)} />
      }
    >
      <View style={styles.header}>
        <GroupSwitcher onManageGroups={() => navigation.navigate('ManageGroups')} />
      </View>

      <View
        style={[
          styles.heroCard,
          {
            backgroundColor: theme.colors.background.default,
            borderColor: theme.colors.neutral[200],
          },
        ]}
      >
        <Text style={[styles.eyebrow, { color: theme.colors.primary[500] }]}>
          {config.eyebrow}
        </Text>
        <Text style={[styles.heroTitle, { color: theme.colors.text.primary }]}>
          {config.title}

