import { useEffect } from 'react';
import { useDispatch } from 'react-redux';
import { AppDispatch } from '../store';
import {
  setAuthFromStorage,
  setError,
  resetLoadingState,
  setUser,
} from '../store/slices/authSlice';
import { fetchFamilies } from '../store/slices/familySlice';
import { fetchUserProfile } from '../store/slices/profileSlice';
import { fetchFamilyFeatureSettings } from '../store/slices/settingsSlice';
import {
  loadOnboardingFromBackend,
  markBackendSyncComplete,
} from '../store/slices/onboardingSlice';
import secureStorage from '../services/secureStorage';
import tokenManager from '../services/tokenManager';
import authAPI from '../api/auth';

export const useAuthInit = () => {
  const dispatch = useDispatch<AppDispatch>();

  useEffect(() => {
    const initializeAuth = async () => {
      const startTime = Date.now();
      console.log('🚀 useAuthInit starting at', new Date().toISOString());

      try {
        // Clear any stuck loading state from previous sessions
        dispatch(resetLoadingState());
        dispatch(setError(null));

        // Check for stored tokens
        const tokens = await secureStorage.getTokens();

        if (tokens && tokens.accessToken) {
          // Set token in manager for immediate use
          tokenManager.setAccessToken(tokens.accessToken);

          // Update Redux state
          dispatch(
            setAuthFromStorage({
              accessToken: tokens.accessToken,
              refreshToken: tokens.refreshToken,
              expiresIn: tokens.expiresIn,
              tokenType: tokens.tokenType,
            })
          );

          dispatch(fetchUserProfile());

          // Fetch families after successful auth initialization
          console.log('🔄 Auth initialized, fetching families...');
          dispatch(fetchFamilies())
            .unwrap()
            .then((data) => {
              console.log('✅ Families fetched on init:', data);
              // Fetch feature settings for the primary (non-network) family
              if (data && data.families.length > 0) {
                const primaryFamily = data.families.find((f) => !f.isNetwork) ?? data.families[0];
                dispatch(fetchFamilyFeatureSettings(primaryFamily.id));
              }
            })
            .catch((error) => {
              console.error('❌ Failed to fetch families on init:', error);
            });

          // Fetch current user to get onboarding status
          // This ensures the app knows the correct onboarding state on session restore
          console.log('🔄 Auth initialized, fetching user profile for onboarding status...');
          try {
            const user = await authAPI.getCurrentUser();
            console.log('🔍 DEBUG: Full user response:', JSON.stringify(user, null, 2));
            console.log('🔍 DEBUG: user.profile:', user.profile);
            dispatch(
              setUser({
                id: user.id,
                email: user.email,
                firstName: user.first_name || '',
                lastName: user.last_name || '',
                avatar: user.avatar_url ?? user.avatar,
                phoneNumber: user.profile?.phone_number ?? user.phone_number,
                dateJoined: user.date_joined || '',
                familyId: user.profile?.primary_family ?? user.primary_family ?? undefined,
              })
            );
            // onboarding_status is nested inside profile from the backend
            const onboardingStatus = user.profile?.onboarding_status;
            console.log('🔍 DEBUG: onboardingStatus extracted:', onboardingStatus);
            const elapsed = Date.now() - startTime;
            if (onboardingStatus) {
              console.log(
                `✅ Onboarding status loaded on init after ${elapsed}ms:`,
                onboardingStatus
              );
              console.log('🔍 DEBUG: onboardingStatus.completed =', onboardingStatus.completed);
              dispatch(loadOnboardingFromBackend(onboardingStatus));
              console.log(`⏱️ backendSyncComplete set to true via useAuthInit after ${elapsed}ms`);
            } else {
              // No onboarding_status in response - mark sync complete so app doesn't wait forever
              console.log(
                `⚠️ No onboarding_status in user response after ${elapsed}ms, using local state`
              );
              dispatch(markBackendSyncComplete());
              console.log(`⏱️ backendSyncComplete set to true (fallback) after ${elapsed}ms`);
            }
          } catch (userError) {
            // Don't block auth init if user fetch fails - onboarding can still work from local state
            const elapsed = Date.now() - startTime;
            console.warn(`⚠️ Failed to fetch user profile after ${elapsed}ms:`, userError);
            console.log(
              '🔍 DEBUG: userError details:',
              JSON.stringify(userError, Object.getOwnPropertyNames(userError))
            );
            dispatch(markBackendSyncComplete());
            console.log(`⏱️ backendSyncComplete set to true (error recovery) after ${elapsed}ms`);
          }
        } else {
          console.log('ℹ️ No stored tokens found, skipping auth init');
        }
      } catch (error) {
        console.error('Failed to initialize auth from storage:', error);
        dispatch(setError(null));
      }
    };

    initializeAuth();
  }, [dispatch]);
};

