export const fetchUserProfile = createAsyncThunk<
  { profile: UserProfile; featureFlags: ProfileFeatureFlags },
  void,
  { rejectValue: string }
>('profile/fetchUserProfile', async (_, { rejectWithValue, dispatch }) => {
  try {
    // Get the user data from the /users/me/ endpoint
    const response = await apiClient.get('/users/me/');
    const userData = response.data;

    // The profile should exist via Django signal, let's check if it's included
    // If not, we'll use default values
    const profile = userData.profile || {};

    const profileData: UserProfile = {
      id: profile.id || userData.id, // Use profile ID, fallback to user ID for compatibility
      user: {
        id: userData.id,
        username: userData.username,
        email: userData.email,
        firstName: userData.first_name || '',
        lastName: userData.last_name || '',
        dateJoined: userData.date_joined,
        avatarUrl: userData.avatar_url || null,
        hasSocialAccount: userData.has_social_account || false,
      },
      primaryFamily: profile.primary_family || null,
      birthDate: profile.birth_date || null,
      phoneNumber: profile.phone_number || '',
      color: profile.color || '#4f46e5',
      timezone: profile.timezone || 'America/New_York',
      address: profile.address || '',
      homeAddress: profile.home_address ?? null,
      bio: profile.bio || '',
      emergencyContactName: profile.emergency_contact_name || '',
      emergencyContactPhone: profile.emergency_contact_phone || '',
    };

    const featureFlags: ProfileFeatureFlags = {
      framesEnabled: Boolean(userData.feature_flags?.frames_enabled ?? false),
      familyPlannerAgentEnabled: Boolean(
        userData.feature_flags?.family_planner_agent_enabled ?? false
      ),
    };

    // Keep the persisted auth slice in sync with the freshly-resolved home
    // address so cold-start bootstrap (before this thunk re-runs) still has
    // a good value for the selector fallback.
    dispatch(setHomeAddress(profileData.homeAddress));

    return { profile: profileData, featureFlags };
  } catch (error) {
    console.error('Failed to fetch profile:', error);
    const message =
      error && typeof error === 'object' && 'response' in error
        ? (error as { response?: { data?: { message?: string } } }).response?.data?.message ||
          'Failed to fetch profile'
        : 'Failed to fetch profile';
    return rejectWithValue(message as string);
  }
});

