export const deleteAccount = createAsyncThunk(
  'profile/deleteAccount',
  async ({ password }: { password?: string }, { rejectWithValue }) => {
    try {
      const response = await apiClient.delete('/users/me/', {
        data: { password },
      });
      return response.data;
    } catch (error) {
      const message =
        error && typeof error === 'object' && 'response' in error
          ? (error as { response?: { data?: { message?: string } } }).response?.data?.message ||
            'Failed to delete account'
          : 'Failed to delete account';
      return rejectWithValue(message);
    }
  }
);

export const fetchDevices = createAsyncThunk(
  'profile/fetchDevices',
  async (_, { rejectWithValue }) => {
    try {
      const response = await apiClient.get('/mobile/devices/');
      return response.data;
    } catch (error) {
      const message =
        error && typeof error === 'object' && 'response' in error
          ? (error as { response?: { data?: { message?: string } } }).response?.data?.message ||
            'Failed to fetch devices'
          : 'Failed to fetch devices';
      return rejectWithValue(message);
    }
  }
);

export const removeDevice = createAsyncThunk(
  'profile/removeDevice',
  async (deviceId: string, { rejectWithValue }) => {
    try {
      await apiClient.delete(`/mobile/devices/${deviceId}/`);
      return deviceId;
    } catch (error) {
      const message =
        error && typeof error === 'object' && 'response' in error
          ? (error as { response?: { data?: { message?: string } } }).response?.data?.message ||
            'Failed to remove device'
          : 'Failed to remove device';
      return rejectWithValue(message);
    }
  }
);

export const toggleBiometric = createAsyncThunk(
  'profile/toggleBiometric',
  async (enable: boolean, { rejectWithValue }) => {
    try {
      const endpoint = enable
        ? '/mobile/auth/biometric_enable/'
        : '/mobile/auth/biometric_disable/';
      const response = await apiClient.post(endpoint);
      return { enabled: enable, ...response.data };
    } catch (error) {
      const message =
        error && typeof error === 'object' && 'response' in error
          ? (error as { response?: { data?: { message?: string } } }).response?.data?.message ||
            'Failed to toggle biometric'
          : 'Failed to toggle biometric';
      return rejectWithValue(message);
    }
  }
);

export const loadPreferences = createAsyncThunk('profile/loadPreferences', async () => {
  const stored = await AsyncStorage.getItem('app_preferences');
  if (stored) {
    const parsed = JSON.parse(stored) as AppPreferences;
    // Backward compatibility: older installs may lack the layout map entirely
    // or only persist the pre-combination coordination/organize buckets.
    parsed.calendarLayoutModeByVariant = {
      ...getDefaultCalendarLayoutModesByVariant(),
      ...parsed.calendarLayoutModeByVariant,
    };
    return parsed;
  }
  return {
    theme: 'auto',
    notificationsEnabled: true,
    biometricEnabled: false,
    offlineMode: 'wifi',
    calendarDefaultView: 'month',
    firstDayOfWeek: 1,
    calendarLayoutModeByVariant: getDefaultCalendarLayoutModesByVariant(),
  } as AppPreferences;
});

export const updatePreferences = createAsyncThunk(
  'profile/updatePreferences',
  async (preferences: AppPreferences) => {
    await AsyncStorage.setItem('app_preferences', JSON.stringify(preferences));
    return preferences;
  }
);

const profileSlice = createSlice({
  name: 'profile',
  initialState,
  reducers: {
    clearProfile: (state) => {
      state.userProfile = null;
      state.devices = [];
      state.preferences = null;
      state.error = null;
      state.updateStatus = 'idle';
    },
    setUpdateStatus: (state, action) => {
      state.updateStatus = action.payload;
    },
  },
  extraReducers: (builder) => {
    builder
      // Fetch profile
      .addCase(fetchUserProfile.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchUserProfile.fulfilled, (state, action) => {
        state.loading = false;
        state.userProfile = action.payload.profile;
        state.featureFlags = action.payload.featureFlags;
      })
      .addCase(fetchUserProfile.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
      })
      // Update profile
      .addCase(updateUserProfile.pending, (state) => {
        state.updateStatus = 'pending';
        state.error = null;
      })
      .addCase(updateUserProfile.fulfilled, (state, action) => {
        state.updateStatus = 'success';
        state.userProfile = action.payload;
      })
      .addCase(updateUserProfile.rejected, (state, action) => {
        state.updateStatus = 'error';
        state.error = action.payload as string;
      })
      // Delete account
      .addCase(deleteAccount.fulfilled, (state) => {
        state.userProfile = null;
        state.devices = [];
        state.preferences = null;
      })
      // Fetch devices
      .addCase(fetchDevices.fulfilled, (state, action) => {
        state.devices = action.payload;
      })
      // Remove device
      .addCase(removeDevice.fulfilled, (state, action) => {
        state.devices = state.devices.filter((d) => d.id !== action.payload);
      })
      // Toggle biometric
      .addCase(toggleBiometric.fulfilled, (state, action) => {
        if (state.preferences) {
          state.preferences.biometricEnabled = action.payload.enabled;
        }
      })
      // Load preferences
      .addCase(loadPreferences.fulfilled, (state, action) => {
        state.preferences = action.payload;
      })
      // Update preferences
      .addCase(updatePreferences.fulfilled, (state, action) => {
        state.preferences = action.payload;
      });
  },
});

export const { clearProfile, setUpdateStatus } = profileSlice.actions;
export default profileSlice.reducer;

export const selectProfileFeatureFlags = (state: RootState) => state.profile.featureFlags;
export const selectFramesEnabled = (state: RootState) =>
  state.profile.featureFlags?.framesEnabled ?? false;
export const selectFamilyPlannerAgentEnabled = (state: RootState) =>
  state.profile.featureFlags?.familyPlannerAgentEnabled ?? false;
