        let nextPlans: GroupPlan[] = [];
        let nextPartyUnits: GroupPartyUnit[] = [];
        let nextConnectedFamilies: ConnectedFamily[] = [];

        if (groupKind === 'META') {
          const [plansPayload, memberships, incomingInvites, adminInvites] = await Promise.all([
            groupsAPI.getPlans(groupId),
            familiesAPI.getMetaMemberships(),
            networkInvitesAPI.list({ scope: 'incoming' }),
            networkInvitesAPI.list({ scope: 'admin' }),
          ]);
          nextPlans = plansPayload;
          const homeFamilyId = currentFamily?.id ? String(currentFamily.id) : null;
          nextConnectedFamilies = memberships
            .filter((membership) => String(membership.meta_family?.id) === groupId)
            .map((membership) => membership.family)
            .filter(Boolean)
            .filter((family) => String(family.id) !== homeFamilyId)
            .map((family) => ({
              id: String(family.id),
              name: family.name,
              memberCount: family.members?.length,
            }))
            .sort((a, b) => a.name.localeCompare(b.name));
          setPendingNetworkRequestCount(
            [...incomingInvites, ...adminInvites].filter(
              (invite) => String(invite.meta_family?.id ?? '') === groupId
            ).length
          );
        } else {
          const [plansPayload, partyUnitsPayload] = await Promise.all([
            groupsAPI.getPlans(groupId),
            groupsAPI.getPartyUnits(groupId),
          ]);
          nextPlans = plansPayload;
          nextPartyUnits = partyUnitsPayload;
          setPendingNetworkRequestCount(0);
        }

        if (latestRequestIdRef.current !== requestId || latestGroupIdRef.current !== groupId) {
          return;
        }

        setPlans(nextPlans);
        setPartyUnits(nextPartyUnits);
        setConnectedFamilies(nextConnectedFamilies);
        setError(null);
      } catch (loadError) {
        if (latestRequestIdRef.current !== requestId || latestGroupIdRef.current !== groupId) {
          return;
        }
        console.error('Failed to load collaboration workspace:', loadError);
        setError('Failed to load collaboration plans.');
      } finally {
        if (latestRequestIdRef.current === requestId && latestGroupIdRef.current === groupId) {
          setIsLoading(false);
          setIsRefreshing(false);
        }
      }
    },
    [config, currentFamily?.id, currentGroup?.groupKind, currentGroup?.id]
  );

  useFocusEffect(
    useCallback(() => {
      let isFocused = true;

      const hydrateWorkspace = async () => {
        await loadWorkspace();
        if (!isFocused || !currentGroup?.id) {
          return;
        }

        const nextMilestone = takePendingWorkspaceMilestone(currentGroup.id);
        setActiveMilestone(nextMilestone);
        if (nextMilestone) {
          haptics.success();
        }
      };

      void hydrateWorkspace();

      return () => {
        isFocused = false;
        setActiveMilestone(null);
      };
    }, [currentGroup?.id, loadWorkspace])
  );

  const responseUnitCount = useMemo(() => {
    if (currentGroup?.groupKind === 'META') {
      return connectedFamilies.length;
    }
    return partyUnits.length;
  }, [connectedFamilies.length, currentGroup?.groupKind, partyUnits.length]);

  const handlePlansSectionLayout = useCallback((event: LayoutChangeEvent) => {
    setPlansSectionY(event.nativeEvent.layout.y);
  }, []);

  const highlightPlansSection = useCallback(() => {
    clearPlansSectionHighlightTimeout();
    setIsPlansSectionHighlighted(true);
    plansSectionHighlightTimeoutRef.current = setTimeout(() => {
      setIsPlansSectionHighlighted(false);
      plansSectionHighlightTimeoutRef.current = null;
    }, PLANS_SECTION_HIGHLIGHT_DURATION_MS);
  }, [clearPlansSectionHighlightTimeout]);

  const handleJumpToPlans = useCallback(() => {
    if (plansSectionY == null) {
      return;
    }

    scrollViewRef.current?.scrollTo({
      y: Math.max(0, plansSectionY - PLANS_SECTION_SCROLL_OFFSET),
      animated: true,
    });
    highlightPlansSection();
  }, [highlightPlansSection, plansSectionY]);

  const openPlansCount = plans.filter((plan) => plan.status === 'OPEN').length;
  const plannerHostFamily = useMemo(() => {
    if (currentFamily?.isHomeGroup) {
      return currentFamily;
    }

    return families.find((family) => family.isHomeGroup) ?? currentFamily;
  }, [currentFamily, families]);
  const plannerEnabled =
    featureFlagsLoaded &&
    familiesReady &&
    currentGroup?.groupKind === 'META' &&
    familyPlannerAgentEnabled &&
    plannerHostFamily?.featureSettings?.agent_enabled === true;
  const pendingInvitationCount =
    currentGroup?.groupKind === 'META'
      ? pendingNetworkRequestCount
      : invitations.filter(
          (invitation) =>
            invitation.familyId === currentGroup?.id &&
            invitation.status.toLowerCase() === 'pending'
        ).length;
  const setupState =
    currentGroup && config
      ? resolveWorkspaceSetupState({
          groupKind: currentGroup.groupKind as CollaborationGroupKind,
          memberCount: currentGroup.memberCount,
          pendingInviteCount: pendingInvitationCount,
          responseUnitCount,
          planCount: plans.length,
        })
      : null;
  const setupStep =
    setupState && setupState !== 'ready' && config ? config.setupSteps[setupState] : null;
  const activeMilestoneMessage =
    activeMilestone && config ? (config.milestoneMessages[activeMilestone] ?? null) : null;

  const handleSetupAction = useCallback(() => {
    if (!setupStep || !currentGroup || !setupState) {
      return;
    }

    if (currentGroup.groupKind === 'META') {
      if (setupState === 'configured') {
        navigation.navigate('Trips', {
          screen: 'CreateTrip',
          params: {
            networkId: currentGroup.id,
            returnTo: 'detail',
          },
        });
        return;
      }

      navigation.navigate('InvitationScreen', {
        groupId: currentGroup.id,
      });
      return;
    }

    if (setupState === 'empty') {
      navigation.navigate('InvitationScreen', {
        groupId: currentGroup.id,
      });
      return;
    }

    if (setupState === 'invited') {
      navigation.navigate('GroupParticipants', {
        groupId: currentGroup.id,
      });
      return;
    }

    navigation.navigate('GroupPlanComposer', {
      groupId: currentGroup.id,
    });
  }, [currentGroup, navigation, setupState, setupStep]);

  if (!currentGroup || !config) {
    return null;
  }

  if (isLoading && !isRefreshing) {
    return (
      <SafeAreaView style={styles.loadingContainer}>
        <ActivityIndicator size="large" color={theme.colors.primary[400]} />
        <Text style={[styles.loadingText, { color: theme.colors.text.secondary }]}>
          Loading collaboration workspace...
        </Text>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView
      style={[styles.container, { backgroundColor: theme.colors.background.paper }]}
      testID="collaboration-workspace-screen"
    >
      <ScrollView
        ref={scrollViewRef}
        testID="collaboration-workspace-scroll"
        contentContainerStyle={styles.scrollContent}
        refreshControl={
          <RefreshControl refreshing={isRefreshing} onRefresh={() => void loadWorkspace(true)} />
        }
      >
        <View style={styles.header}>
          <GroupSwitcher onManageGroups={() => navigation.navigate('ManageGroups')} />
        </View>

        <View
          style={[
            styles.heroCard,
            {
              backgroundColor: theme.colors.background.default,
              borderColor: theme.colors.neutral[200],
            },
          ]}
        >
          <Text style={[styles.eyebrow, { color: theme.colors.primary[500] }]}>
            {config.eyebrow}
          </Text>
          <Text style={[styles.heroTitle, { color: theme.colors.text.primary }]}>
            {config.title}
          </Text>
          <Text style={[styles.heroDescription, { color: theme.colors.text.secondary }]}>
            {currentGroup.description || config.description}
          </Text>

          <View style={styles.heroStats}>
            <View
              testID="collaboration-response-unit-stat"
              style={[styles.statPill, { backgroundColor: theme.colors.primary[50] }]}
            >
              <Text
                testID="collaboration-response-unit-stat-value"
                style={[styles.statValue, { color: theme.colors.primary[500] }]}
              >
                {responseUnitCount}
              </Text>
              <Text
                testID="collaboration-response-unit-stat-label"
                style={[styles.statLabel, { color: theme.colors.text.secondary }]}
              >
                {config.statLabel}
              </Text>
            </View>
            <TouchableOpacity
              accessibilityRole="button"
              testID="collaboration-open-plans-stat"
              style={[styles.statPill, { backgroundColor: theme.colors.secondary[50] }]}
              onPress={handleJumpToPlans}
            >
              <Text style={[styles.statValue, { color: theme.colors.secondary[500] }]}>
                {openPlansCount}
              </Text>
              <Text style={[styles.statLabel, { color: theme.colors.text.secondary }]}>
                Open Plans
              </Text>
            </TouchableOpacity>
          </View>

          {activeMilestoneMessage ? (
            <View
              testID="collaboration-success-card"
              style={[
                styles.successCard,
                {
                  backgroundColor: theme.colors.secondary[50],
                  borderColor: theme.colors.secondary[500],
                },
              ]}
            >
              <View style={styles.successContent}>
                <Text style={[styles.successTitle, { color: theme.colors.text.primary }]}>
                  {activeMilestoneMessage.title}
                </Text>
                <Text style={[styles.successBody, { color: theme.colors.text.secondary }]}>
                  {activeMilestoneMessage.description}
                </Text>
              </View>
              <TouchableOpacity
                testID="collaboration-success-dismiss"
                onPress={() => setActiveMilestone(null)}
              >
                <Text style={[styles.successDismissText, { color: theme.colors.secondary[500] }]}>
                  Dismiss
                </Text>
              </TouchableOpacity>
            </View>
          ) : null}

          {setupStep ? (
            <View
              testID="collaboration-setup-card"
              style={[
                styles.setupCard,
                {
                  backgroundColor: theme.colors.primary[50],
                  borderColor: theme.colors.primary[400],
                },
              ]}
            >
              <Text style={[styles.setupEyebrow, { color: theme.colors.primary[500] }]}>
                {config.nextActionLabel}
              </Text>
              <Text style={[styles.setupTitle, { color: theme.colors.text.primary }]}>
                {setupStep.title}
              </Text>
              <Text style={[styles.setupDescription, { color: theme.colors.text.secondary }]}>
                {setupStep.description}
              </Text>
              <TouchableOpacity
                testID="collaboration-setup-cta"
                style={[styles.setupButton, { backgroundColor: theme.colors.primary[500] }]}
                onPress={handleSetupAction}
              >
                <Text style={[styles.setupButtonText, { color: theme.colors.text.inverse }]}>
                  {setupStep.ctaLabel}
                </Text>
              </TouchableOpacity>
            </View>
          ) : (
            <View
              testID="collaboration-ready-banner"
              style={[
                styles.readyBanner,
                {
                  backgroundColor: theme.colors.secondary[50],
                  borderColor: theme.colors.secondary[500],
                },
              ]}
            >
              <Text style={[styles.readyBannerText, { color: theme.colors.secondary[500] }]}>
                {config.readyStateLabel}
              </Text>
            </View>
          )}

          <View style={styles.heroActions}>
            <TouchableOpacity
              testID="collaboration-primary-action"
              style={[styles.primaryAction, { backgroundColor: theme.colors.primary[500] }]}
              onPress={() => {
                if (currentGroup.groupKind === 'META') {
                  navigation.navigate('Trips', {
                    screen: 'CreateTrip',
                    params: {
                      networkId: currentGroup.id,
                      returnTo: 'detail',
                    },
                  });
                  return;
                }

                navigation.navigate('GroupPlanComposer', {
                  groupId: currentGroup.id,
                });
              }}
            >
              <Ionicons
                name={currentGroup.groupKind === 'META' ? 'airplane-outline' : 'add-circle-outline'}
                size={18}
                color={theme.colors.text.inverse}
              />
              <Text style={[styles.primaryActionText, { color: theme.colors.text.inverse }]}>
                {config.primaryActionLabel}
              </Text>
            </TouchableOpacity>

            {plannerEnabled ? (
              <TouchableOpacity
                testID="collaboration-planner-action"
                style={[
                  styles.secondaryAction,
                  {
                    borderColor: theme.colors.neutral[300],
                    backgroundColor: theme.colors.background.default,
                  },
                ]}
                onPress={() =>
                  navigation.navigate('FamilyPlanner', {
                    sourceScreen: 'family_network',
                    familyId: plannerHostFamily?.id ?? null,
                    tripId: null,
                    tripName: undefined,
                    eventId: null,
                    groupId: currentGroup.id,
                  })
                }
              >
                <Ionicons
                  name="chatbubble-ellipses-outline"
                  size={18}
                  color={theme.colors.text.primary}
                />
                <Text style={[styles.secondaryActionText, { color: theme.colors.text.primary }]}>
                  Chat With Planner
                </Text>
              </TouchableOpacity>
            ) : null}

            {config.secondaryActionLabel ? (
              <TouchableOpacity
                testID="collaboration-secondary-action"
                style={[
                  styles.secondaryAction,
                  {
                    borderColor: theme.colors.neutral[300],
                    backgroundColor: theme.colors.background.default,
                  },
                ]}
                onPress={() => {
                  if (currentGroup.groupKind === 'META') {
                    navigation.navigate('GroupPlanComposer', {
                      groupId: currentGroup.id,
                    });
                    return;
                  }

                  navigation.navigate('GroupParticipants', {
                    groupId: currentGroup.id,
                  });
                }}
              >
                <Ionicons
                  name={
                    currentGroup.groupKind === 'META' ? 'git-compare-outline' : 'people-outline'
                  }
                  size={18}
                  color={theme.colors.text.primary}
                />
                <Text style={[styles.secondaryActionText, { color: theme.colors.text.primary }]}>
                  {config.secondaryActionLabel}
                </Text>
              </TouchableOpacity>
            ) : null}

            {config.manageActionLabel ? (
              <TouchableOpacity
                testID="collaboration-manage-action"
                style={[
                  styles.secondaryAction,
                  {
                    borderColor: theme.colors.neutral[300],
                    backgroundColor: theme.colors.background.default,
                  },
                ]}
                onPress={() => {
                  if (currentGroup.groupKind === 'META') {
                    navigation.navigate('InvitationScreen', {
                      groupId: currentGroup.id,
                    });
                    return;
                  }

                  navigation.navigate('MemberManagement', {
                    groupId: currentGroup.id,
                  });
                }}
              >
                <Ionicons
                  name={
                    currentGroup.groupKind === 'META'
                      ? 'git-network-outline'
                      : 'people-circle-outline'
                  }
                  size={18}
                  color={theme.colors.text.primary}
                />
                <Text style={[styles.secondaryActionText, { color: theme.colors.text.primary }]}>
                  {config.manageActionLabel}
                </Text>
              </TouchableOpacity>
            ) : null}

            <TouchableOpacity
              testID="collaboration-settings-action"
              style={[
                styles.secondaryAction,
                {
                  borderColor: theme.colors.neutral[300],
                  backgroundColor: theme.colors.background.default,
                },
              ]}
              onPress={() =>
                navigation.navigate('FamilySettings', {
                  groupId: currentGroup.id,
                })
              }
            >
              <Ionicons name="settings-outline" size={18} color={theme.colors.text.primary} />
              <Text style={[styles.secondaryActionText, { color: theme.colors.text.primary }]}>
                Group Settings
              </Text>
            </TouchableOpacity>
          </View>
        </View>

        {currentGroup.groupKind === 'META' ? (
          <View style={styles.section}>
            <Text style={[styles.sectionTitle, { color: theme.colors.text.primary }]}>Trips</Text>
            <Text style={[styles.sectionSubtitle, { color: theme.colors.text.secondary }]}>
              Start shared travel plans for connected families.
            </Text>
            <View
              style={[
                styles.emptyCard,
                {
                  backgroundColor: theme.colors.background.default,
                  borderColor: theme.colors.neutral[200],
                },
              ]}
            >
              <Text style={[styles.emptyTitle, { color: theme.colors.text.primary }]}>
                Plan the next shared trip
              </Text>
              <Text style={[styles.emptyBody, { color: theme.colors.text.secondary }]}>
                Launch trip creation from this network to include multiple connected families at
                once.
              </Text>
            </View>
          </View>
        ) : null}

        {currentGroup.groupKind === 'META' ? (
          <View style={styles.section}>
            <Text style={[styles.sectionTitle, { color: theme.colors.text.primary }]}>
              Connected Families
            </Text>
            <Text style={[styles.sectionSubtitle, { color: theme.colors.text.secondary }]}>
              Families participating in this network.
            </Text>
            {connectedFamilies.length === 0 ? (
              <View
                style={[
                  styles.emptyCard,
                  {
                    backgroundColor: theme.colors.background.default,
                    borderColor: theme.colors.neutral[200],
                  },
                ]}
              >
                <Text style={[styles.emptyTitle, { color: theme.colors.text.primary }]}>
                  {config.responseUnitEmptyTitle}
                </Text>
                <Text style={[styles.emptyBody, { color: theme.colors.text.secondary }]}>
                  {config.responseUnitEmptyBody}
                </Text>
              </View>
            ) : (
              connectedFamilies.map((family) => (
                <View
                  key={family.id}
                  style={[
                    styles.planCard,
                    {
                      backgroundColor: theme.colors.background.default,
                      borderColor: theme.colors.neutral[200],
                    },
                  ]}
                >
                  <Text style={[styles.planTitle, { color: theme.colors.text.primary }]}>
                    {family.name}
                  </Text>
                  <Text style={[styles.planMeta, { color: theme.colors.text.secondary }]}>
                    {family.memberCount ?? 0} members
                  </Text>
                </View>
              ))
            )}
          </View>
        ) : null}

        <View style={styles.section} onLayout={handlePlansSectionLayout}>
          <View
            testID="collaboration-plans-section"
            style={[
              styles.sectionJumpTarget,
              {
                backgroundColor: isPlansSectionHighlighted
                  ? theme.colors.primary[50]
                  : theme.colors.background.paper,
                borderColor: isPlansSectionHighlighted
                  ? theme.colors.primary[400]
                  : theme.colors.background.paper,
              },
            ]}
          >
            <Text style={[styles.sectionTitle, { color: theme.colors.text.primary }]}>
              {config.eyebrow}
            </Text>
            <Text style={[styles.sectionSubtitle, { color: theme.colors.text.secondary }]}>
              {config.plansSubtitle}
            </Text>

            {error ? (
              <View
                style={[
                  styles.emptyCard,
                  {
                    backgroundColor: theme.colors.background.default,
                    borderColor: theme.colors.error.light,
                  },
                ]}
              >
                <Text style={[styles.emptyTitle, { color: theme.colors.text.primary }]}>
                  {error}
                </Text>
              </View>
            ) : null}

            {plans.length === 0 ? (
              <View
                style={[
                  styles.emptyCard,
                  {
                    backgroundColor: theme.colors.background.default,
                    borderColor: theme.colors.neutral[200],
                  },
                ]}
              >
                <Text style={[styles.emptyTitle, { color: theme.colors.text.primary }]}>
                  No plans yet
                </Text>
                <Text style={[styles.emptyBody, { color: theme.colors.text.secondary }]}>
                  {config.emptyPlanBody}
                </Text>
              </View>
            ) : (
              plans.map((plan) => {
                const tone = statusTone[plan.status];
                const metaLabels = getPlanCardMeta(plan);
                return (
                  <TouchableOpacity
                    key={plan.id}
                    testID={`collaboration-plan-card-${plan.id}`}
                    style={[
                      styles.planCard,
                      {
                        backgroundColor: theme.colors.background.default,
                        borderColor: theme.colors.neutral[200],
                      },
                    ]}
                    onPress={() =>
                      navigation.navigate('GroupPlanDetail', {
                        planId: plan.id,
                        groupId: currentGroup.id,
                      })
                    }
                  >
                    <View style={styles.planHeader}>
                      <Text style={[styles.planTitle, { color: theme.colors.text.primary }]}>
                        {plan.title}
                      </Text>
                      <View style={[styles.statusBadge, { backgroundColor: tone.background }]}>
                        <Text style={[styles.statusBadgeText, { color: tone.color }]}>
                          {plan.status}
                        </Text>
                      </View>
                    </View>

                    <View style={styles.planMetaRow}>
                      {metaLabels.map((label, index) => (
                        <Text
                          key={`${plan.id}-meta-${index}`}
                          testID={`collaboration-plan-card-meta-${plan.id}-${index}`}
                          style={[styles.planMeta, { color: theme.colors.text.secondary }]}
                        >
                          {label}
                        </Text>
                      ))}
                    </View>

                    {plan.created_by ? (
                      <Text style={[styles.planCreator, { color: theme.colors.text.secondary }]}>
                        Proposed by{' '}
                        {[plan.created_by.first_name, plan.created_by.last_name]
                          .filter(Boolean)
                          .join(' ') ||
                          plan.created_by.username ||
                          'Unknown'}
                      </Text>
                    ) : null}

                    {plan.description ? (
                      <Text
                        style={[styles.planDescription, { color: theme.colors.text.secondary }]}
                      >
                        {plan.description}
                      </Text>
                    ) : null}
                  </TouchableOpacity>
                );
              })
            )}
          </View>
        </View>
      </ScrollView>
    </SafeAreaView>
  );
};

