  (groupsAPI.getPlans as jest.Mock).mockResolvedValue([]);
  (groupsAPI.getPartyUnits as jest.Mock).mockResolvedValue([]);
  (familiesAPI.getMetaMemberships as jest.Mock).mockResolvedValue([]);

  const store = configureStore({
    reducer: {
      families: familyReducer,
      profile: () => ({
        featureFlags: {
          familyPlannerAgentEnabled: true,
        },
      }),
    },
  });

  const homeFamily = {
    ...makeGroup('family-home', 'Coach Family'),
    groupKind: 'IMMEDIATE' as const,
    isHomeGroup: true,
    featureSettings: {
      trips_enabled: false,
      households_enabled: false,
      groceries_enabled: false,
      recipes_enabled: false,
      meals_enabled: false,
      agent_enabled: true,
    },
  };
  const network = {
    ...makeGroup('network-planner', 'Tournament Families'),
    groupKind: 'META' as const,
  };
  store.dispatch(setFamilies([homeFamily, network]));
  store.dispatch(setCurrentFamily(homeFamily));
  store.dispatch(setCurrentGroup(network));

  const screen = render(
    <Provider store={store}>
      <GroupWorkspace />
    </Provider>
  );

  await waitFor(() => expect(screen.getByTestId('collaboration-planner-action')).toBeTruthy());
  expect(screen.getByText('Chat With Planner')).toBeTruthy();
  expect(screen.getByText('Start Cross-Family Plan')).toBeTruthy();

  fireEvent.press(screen.getByTestId('collaboration-planner-action'));

  expect(mockNavigate).toHaveBeenCalledWith('FamilyPlanner', {
    sourceScreen: 'family_network',
    familyId: 'family-home',
