import React from 'react';
import { act, fireEvent, render, waitFor, within } from '@testing-library/react-native';
import { configureStore } from '@reduxjs/toolkit';
import { Provider } from 'react-redux';
import GroupWorkspace from '../GroupWorkspace';
import familyReducer, {
  setCurrentFamily,
  setCurrentGroup,
  setFamilies,
  type Family,
} from '../../../store/slices/familySlice';
import groupsAPI from '../../../api/groups';
import familiesAPI from '../../../api/families';
import networkInvitesAPI from '../../../api/networkInvites';
import {
  publishWorkspaceMilestone,
  resetWorkspaceMilestonesForTests,
} from '../../collaboration/workspaceMilestones';

const mockScrollTo = jest.fn();
const mockNavigate = jest.fn();

jest.mock('react-native', () => {
  const React = require('react');
  const actual = jest.requireActual('react-native');

  const ScrollView = React.forwardRef(
    (
      {
        children,
        contentContainerStyle,
        style,
        ...props
      }: { children?: React.ReactNode; contentContainerStyle?: object; style?: object },
      ref: React.Ref<{ scrollTo: jest.Mock }>
    ) => {
      React.useImperativeHandle(
        ref,
        () => ({
          scrollTo: mockScrollTo,
        }),
        []
      );

      return (
        <actual.View {...props} style={[style, contentContainerStyle]}>
          {children}
        </actual.View>
      );
    }
  );
  ScrollView.displayName = 'MockScrollView';

  return new Proxy(actual, {
    get(target, prop) {
      if (prop === 'ScrollView') {
        return ScrollView;
      }

      return target[prop as keyof typeof target];
    },
  });
});

