type Deferred<T> = {
  promise: Promise<T>;
  resolve: (value: T) => void;
};

const deferred = <T,>(): Deferred<T> => {
  let resolve!: (value: T) => void;
  const promise = new Promise<T>((res) => {
    resolve = res;
  });
  return { promise, resolve };
};

const makeGroup = (id: string, name: string): Family => ({
  id,
  name,
  description: '',
  created: '2026-03-08T12:00:00.000Z',
  isActive: true,
  memberCount: 1,
  createdBy: '1',
  settings: {},
  groupKind: 'TEAM',
  isHomeGroup: false,
  featureSettings: {
    trips_enabled: false,
    households_enabled: false,
    groceries_enabled: false,
    recipes_enabled: false,
    meals_enabled: false,
  },
  partyUnitCount: 0,
  representedMemberCount: 0,
});

describe('GroupWorkspace', () => {
