    jest.clearAllMocks();
    mockScrollTo.mockClear();
    mockNavigate.mockClear();
    (networkInvitesAPI.list as jest.Mock).mockResolvedValue([]);
    resetWorkspaceMilestonesForTests();
  });

  it('renders team-specific collaboration actions without household copy', async () => {
    (groupsAPI.getPlans as jest.Mock).mockResolvedValue([]);
