import AsyncStorage from '@react-native-async-storage/async-storage';
import apiClient from '../../api/client';
import { RootState } from '..';
import { ProfileUpdatePayload } from '../../screens/profile/types';
import { setHomeAddress } from './authSlice';

export interface UserProfile {
  id: string;
  user: {
    id: number;
    username: string;
    email: string;
    firstName: string;
    lastName: string;
    dateJoined: string;
    avatarUrl: string | null;
    hasSocialAccount: boolean;
  };
  primaryFamily: string | null;
  birthDate: string | null;
  phoneNumber: string;
  color: string;
  timezone: string;
  address: string;
  /**
   * Read-only resolved shared home address from the family's primary
   * household. Preferred origin for travel estimates and distance
   * calculations.
   */
  homeAddress: string | null;
  bio: string;
  emergencyContactName: string;
  emergencyContactPhone: string;
}

export type CalendarLayoutMode = 'date-grid' | 'member-columns';
export type CalendarLayoutVariant = 'coordination' | 'organize' | 'combination';

export function getDefaultCalendarLayoutMode(variant: string): CalendarLayoutMode {
  return variant === 'organize' || variant === 'combination' ? 'member-columns' : 'date-grid';
}

function getDefaultCalendarLayoutModesByVariant(): Record<
  CalendarLayoutVariant,
  CalendarLayoutMode
> {
  return {
    coordination: getDefaultCalendarLayoutMode('coordination'),
    organize: getDefaultCalendarLayoutMode('organize'),
    combination: getDefaultCalendarLayoutMode('combination'),
  };
}

export interface AppPreferences {
  theme: 'light' | 'dark' | 'auto';
  notificationsEnabled: boolean;
  biometricEnabled: boolean;
  offlineMode: 'wifi' | 'always' | 'never';
  calendarDefaultView: 'day' | 'week' | 'month';
  firstDayOfWeek: 0 | 1 | 6;
  calendarLayoutModeByVariant?: Record<CalendarLayoutVariant, CalendarLayoutMode>;
}

export interface MobileDevice {
  id: string;
  deviceId: string;
  deviceName: string;
  platform: 'ios' | 'android';
  lastActive: string;
  isCurrent: boolean;
}

export interface ProfileFeatureFlags {
  framesEnabled: boolean;
  familyPlannerAgentEnabled: boolean;
}

interface ProfileState {
  userProfile: UserProfile | null;
  loading: boolean;
  error: string | null;
  updateStatus: 'idle' | 'pending' | 'success' | 'error';
  devices: MobileDevice[];
  preferences: AppPreferences | null;
  featureFlags: ProfileFeatureFlags;
}

const initialState: ProfileState = {
  userProfile: null,
  loading: false,
  error: null,
  updateStatus: 'idle',
  devices: [],
  preferences: {
    theme: 'auto',
    notificationsEnabled: true,
    biometricEnabled: false,
    offlineMode: 'wifi',
    calendarDefaultView: 'month',
    firstDayOfWeek: 1,
    calendarLayoutModeByVariant: getDefaultCalendarLayoutModesByVariant(),
  },
  featureFlags: {
    framesEnabled: false,
    familyPlannerAgentEnabled: false,
  },
};

// Async thunks
export const fetchUserProfile = createAsyncThunk<
  { profile: UserProfile; featureFlags: ProfileFeatureFlags },
  void,
  { rejectValue: string }
>('profile/fetchUserProfile', async (_, { rejectWithValue, dispatch }) => {
  try {
    // Get the user data from the /users/me/ endpoint
    const response = await apiClient.get('/users/me/');
    const userData = response.data;

    // The profile should exist via Django signal, let's check if it's included
    // If not, we'll use default values
    const profile = userData.profile || {};

    const profileData: UserProfile = {
      id: profile.id || userData.id, // Use profile ID, fallback to user ID for compatibility
      user: {
        id: userData.id,
        username: userData.username,
        email: userData.email,
        firstName: userData.first_name || '',
        lastName: userData.last_name || '',
        dateJoined: userData.date_joined,
        avatarUrl: userData.avatar_url || null,
        hasSocialAccount: userData.has_social_account || false,
      },
      primaryFamily: profile.primary_family || null,
      birthDate: profile.birth_date || null,
      phoneNumber: profile.phone_number || '',
      color: profile.color || '#4f46e5',
      timezone: profile.timezone || 'America/New_York',
      address: profile.address || '',
      homeAddress: profile.home_address ?? null,
      bio: profile.bio || '',
      emergencyContactName: profile.emergency_contact_name || '',
      emergencyContactPhone: profile.emergency_contact_phone || '',
    };

    const featureFlags: ProfileFeatureFlags = {
      framesEnabled: Boolean(userData.feature_flags?.frames_enabled ?? false),
      familyPlannerAgentEnabled: Boolean(
        userData.feature_flags?.family_planner_agent_enabled ?? false
      ),
    };

    // Keep the persisted auth slice in sync with the freshly-resolved home
    // address so cold-start bootstrap (before this thunk re-runs) still has
    // a good value for the selector fallback.
    dispatch(setHomeAddress(profileData.homeAddress));

    return { profile: profileData, featureFlags };
  } catch (error) {
    console.error('Failed to fetch profile:', error);
    const message =
      error && typeof error === 'object' && 'response' in error
        ? (error as { response?: { data?: { message?: string } } }).response?.data?.message ||
          'Failed to fetch profile'
        : 'Failed to fetch profile';
    return rejectWithValue(message as string);
  }
});

export const updateUserProfile = createAsyncThunk(
  'profile/updateUserProfile',
  async (updates: ProfileUpdatePayload, { rejectWithValue, getState, dispatch }) => {
    try {
      // Get the profile ID from the current state
      const state = getState() as RootState;
      const profileId = state.profile.userProfile?.id;

      if (!profileId) {
        return rejectWithValue('Profile ID not found');
      }

      // Map camelCase to snake_case for the API
      const apiUpdates: Record<string, unknown> = {};

      if (updates.firstName !== undefined) apiUpdates.first_name = updates.firstName;
      if (updates.lastName !== undefined) apiUpdates.last_name = updates.lastName;
      if (updates.email !== undefined) apiUpdates.email = updates.email;
      if (updates.phoneNumber !== undefined) apiUpdates.phone_number = updates.phoneNumber;
      if (updates.birthDate !== undefined) apiUpdates.birth_date = updates.birthDate;
      if (updates.timezone !== undefined) apiUpdates.timezone = updates.timezone;
      if (updates.address !== undefined) apiUpdates.address = updates.address;
      if (updates.bio !== undefined) apiUpdates.bio = updates.bio;
      if (updates.emergencyContactName !== undefined)
        apiUpdates.emergency_contact_name = updates.emergencyContactName;
      if (updates.emergencyContactPhone !== undefined)
        apiUpdates.emergency_contact_phone = updates.emergencyContactPhone;
      if (updates.primaryFamily !== undefined) apiUpdates.primary_family = updates.primaryFamily;

      // Use PATCH for partial updates to the correct endpoint
      const response = await apiClient.patch(`/profiles/${profileId}/`, apiUpdates);

      // Map the response back to camelCase
      const profileData: UserProfile = {
        id: response.data.user?.id || profileId,
        user: {
          id: response.data.user?.id || state.profile.userProfile?.user.id || 0,
          username: response.data.user?.username || state.profile.userProfile?.user.username || '',
          email:
            response.data.user?.email ||
            updates.email ||
            state.profile.userProfile?.user.email ||
            '',
          firstName:
            response.data.user?.first_name ||
            updates.firstName ||
            state.profile.userProfile?.user.firstName ||
            '',
          lastName:
            response.data.user?.last_name ||
            updates.lastName ||
            state.profile.userProfile?.user.lastName ||
            '',
          dateJoined:
            response.data.user?.date_joined || state.profile.userProfile?.user.dateJoined || '',
          avatarUrl:
            response.data.user?.avatar_url || state.profile.userProfile?.user.avatarUrl || null,
          hasSocialAccount:
            response.data.user?.has_social_account ||
            state.profile.userProfile?.user.hasSocialAccount ||
            false,
        },
        primaryFamily:
          response.data.primary_family || state.profile.userProfile?.primaryFamily || null,
        birthDate:
          response.data.birth_date ||
          updates.birthDate ||
          state.profile.userProfile?.birthDate ||
          null,
        phoneNumber:
          response.data.phone_number ||
          updates.phoneNumber ||
          state.profile.userProfile?.phoneNumber ||
          '',
        color: response.data.color || state.profile.userProfile?.color || '#4f46e5',
        timezone:
          response.data.timezone ||
          updates.timezone ||
          state.profile.userProfile?.timezone ||
          'America/New_York',
        address:
          response.data.address || updates.address || state.profile.userProfile?.address || '',
        homeAddress: response.data.home_address ?? state.profile.userProfile?.homeAddress ?? null,
        bio: response.data.bio || updates.bio || state.profile.userProfile?.bio || '',
        emergencyContactName:
          response.data.emergency_contact_name ||
          updates.emergencyContactName ||
          state.profile.userProfile?.emergencyContactName ||
          '',
        emergencyContactPhone:
          response.data.emergency_contact_phone ||
          updates.emergencyContactPhone ||
          state.profile.userProfile?.emergencyContactPhone ||
          '',
      };

      // Keep the persisted auth slice in sync so the selector fallback
      // reflects the edit immediately on next cold start.
      dispatch(setHomeAddress(profileData.homeAddress));

      return profileData;
    } catch (error) {
      const message =
        error && typeof error === 'object' && 'response' in error
          ? (error as { response?: { data?: { message?: string } } }).response?.data?.message ||
            'Failed to update profile'
          : 'Failed to update profile';
      return rejectWithValue(message);
    }
  }
);

export const deleteAccount = createAsyncThunk(
  'profile/deleteAccount',
  async ({ password }: { password?: string }, { rejectWithValue }) => {
    try {
      const response = await apiClient.delete('/users/me/', {
        data: { password },
      });
      return response.data;
    } catch (error) {
      const message =
        error && typeof error === 'object' && 'response' in error
          ? (error as { response?: { data?: { message?: string } } }).response?.data?.message ||
            'Failed to delete account'
          : 'Failed to delete account';
      return rejectWithValue(message);
    }
  }
);

export const fetchDevices = createAsyncThunk(
  'profile/fetchDevices',
  async (_, { rejectWithValue }) => {
    try {
      const response = await apiClient.get('/mobile/devices/');
      return response.data;
    } catch (error) {
      const message =
        error && typeof error === 'object' && 'response' in error
          ? (error as { response?: { data?: { message?: string } } }).response?.data?.message ||
            'Failed to fetch devices'
          : 'Failed to fetch devices';
      return rejectWithValue(message);
    }
  }
);

export const removeDevice = createAsyncThunk(
  'profile/removeDevice',
  async (deviceId: string, { rejectWithValue }) => {
    try {
      await apiClient.delete(`/mobile/devices/${deviceId}/`);
      return deviceId;
    } catch (error) {
      const message =
        error && typeof error === 'object' && 'response' in error
          ? (error as { response?: { data?: { message?: string } } }).response?.data?.message ||
            'Failed to remove device'
          : 'Failed to remove device';
      return rejectWithValue(message);
    }
  }
);

export const toggleBiometric = createAsyncThunk(
  'profile/toggleBiometric',
  async (enable: boolean, { rejectWithValue }) => {
    try {
      const endpoint = enable
        ? '/mobile/auth/biometric_enable/'
        : '/mobile/auth/biometric_disable/';
      const response = await apiClient.post(endpoint);
      return { enabled: enable, ...response.data };
    } catch (error) {
      const message =
        error && typeof error === 'object' && 'response' in error
          ? (error as { response?: { data?: { message?: string } } }).response?.data?.message ||
            'Failed to toggle biometric'
          : 'Failed to toggle biometric';
      return rejectWithValue(message);
    }
  }
);

export const loadPreferences = createAsyncThunk('profile/loadPreferences', async () => {
  const stored = await AsyncStorage.getItem('app_preferences');
  if (stored) {
    const parsed = JSON.parse(stored) as AppPreferences;
    // Backward compatibility: older installs may lack the layout map entirely
    // or only persist the pre-combination coordination/organize buckets.
    parsed.calendarLayoutModeByVariant = {
      ...getDefaultCalendarLayoutModesByVariant(),
      ...parsed.calendarLayoutModeByVariant,
    };
    return parsed;
  }
  return {
    theme: 'auto',
    notificationsEnabled: true,
    biometricEnabled: false,
    offlineMode: 'wifi',
    calendarDefaultView: 'month',
    firstDayOfWeek: 1,
    calendarLayoutModeByVariant: getDefaultCalendarLayoutModesByVariant(),
  } as AppPreferences;
});

export const updatePreferences = createAsyncThunk(
  'profile/updatePreferences',
  async (preferences: AppPreferences) => {
    await AsyncStorage.setItem('app_preferences', JSON.stringify(preferences));
    return preferences;
  }
);

const profileSlice = createSlice({
  name: 'profile',
  initialState,
  reducers: {
    clearProfile: (state) => {
      state.userProfile = null;
      state.devices = [];
      state.preferences = null;
      state.error = null;
      state.updateStatus = 'idle';
    },
    setUpdateStatus: (state, action) => {
      state.updateStatus = action.payload;
    },
  },
  extraReducers: (builder) => {
    builder
      // Fetch profile
      .addCase(fetchUserProfile.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchUserProfile.fulfilled, (state, action) => {
        state.loading = false;
        state.userProfile = action.payload.profile;
        state.featureFlags = action.payload.featureFlags;
      })
      .addCase(fetchUserProfile.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
      })
      // Update profile
      .addCase(updateUserProfile.pending, (state) => {
        state.updateStatus = 'pending';
        state.error = null;
      })
      .addCase(updateUserProfile.fulfilled, (state, action) => {
        state.updateStatus = 'success';
        state.userProfile = action.payload;
      })
