const getPlanCardMeta = (plan: GroupPlan): string[] => {
  if (plan.mode !== 'LEGACY_SEPARATE' && plan.plan_options.length > 0) {
    const responderCount = new Set(
      (plan.option_responses ?? []).map((response) => response.response_unit.id)
    ).size;

    return [
      templateLabel[plan.template],
      `${plan.plan_options.length} ${plan.mode === 'TIME_ONLY' ? 'time options' : 'linked options'}`,
      responderCount > 0
        ? `${responderCount} ${responderCount === 1 ? 'responder' : 'responders'}`
        : 'Awaiting responses',
    ];
  }

  return [
    templateLabel[plan.template],
    `${plan.time_options.length} time options`,
