                  >
                    <View style={styles.planHeader}>
                      <Text style={[styles.planTitle, { color: theme.colors.text.primary }]}>
                        {plan.title}
                      </Text>
                      <View style={[styles.statusBadge, { backgroundColor: tone.background }]}>
                        <Text style={[styles.statusBadgeText, { color: tone.color }]}>
                          {plan.status}
                        </Text>
                      </View>
                    </View>

                    <View style={styles.planMetaRow}>
                      {metaLabels.map((label, index) => (
                        <Text
                          key={`${plan.id}-meta-${index}`}
                          testID={`collaboration-plan-card-meta-${plan.id}-${index}`}
                          style={[styles.planMeta, { color: theme.colors.text.secondary }]}
                        >
                          {label}
                        </Text>
                      ))}
                    </View>

                    {plan.created_by ? (
                      <Text style={[styles.planCreator, { color: theme.colors.text.secondary }]}>
                        Proposed by{' '}
                        {[plan.created_by.first_name, plan.created_by.last_name]
                          .filter(Boolean)
                          .join(' ') ||
                          plan.created_by.username ||
                          'Unknown'}
                      </Text>
                    ) : null}

                    {plan.description ? (
                      <Text
                        style={[styles.planDescription, { color: theme.colors.text.secondary }]}
                      >
                        {plan.description}
                      </Text>
                    ) : null}
                  </TouchableOpacity>
                );
              })
            )}
          </View>
        </View>
      </ScrollView>
    </SafeAreaView>
  );
};

