const getPlanCardMeta = (plan: GroupPlan): string[] => {
  if (plan.mode !== 'LEGACY_SEPARATE' && plan.plan_options.length > 0) {
    const responderCount = new Set(
      (plan.option_responses ?? []).map((response) => response.response_unit.id)
    ).size;

    return [
      templateLabel[plan.template],
      `${plan.plan_options.length} ${plan.mode === 'TIME_ONLY' ? 'time options' : 'linked options'}`,
      responderCount > 0
        ? `${responderCount} ${responderCount === 1 ? 'responder' : 'responders'}`
        : 'Awaiting responses',
    ];
  }

  return [
    templateLabel[plan.template],
    `${plan.time_options.length} time options`,
    `${plan.choice_options.length} choices`,
  ];
};

const CollaborationWorkspaceRouter: React.FC = () => {
  const theme = useTheme();
  const navigation = useNavigation<NavigationProp<ParamListBase>>();
  const dispatch = useDispatch<AppDispatch>();
  const currentGroup = useSelector(selectCurrentGroup);
  const currentFamily = useSelector(selectCurrentFamily);
  const families = useSelector(selectFamilies);
  const invitations = useSelector(selectInvitations);
  const familyPlannerAgentEnabled = useSelector(selectFamilyPlannerAgentEnabled);
  const featureFlagsLoaded = useSelector(selectFeatureFlagsLoaded);
  const familiesReady = useSelector(selectFamiliesReady);
  const config = getCollaborationConfig(currentGroup?.groupKind);
  const [plans, setPlans] = useState<GroupPlan[]>([]);
  const [partyUnits, setPartyUnits] = useState<GroupPartyUnit[]>([]);
  const [connectedFamilies, setConnectedFamilies] = useState<ConnectedFamily[]>([]);
  const [pendingNetworkRequestCount, setPendingNetworkRequestCount] = useState(0);
  const [activeMilestone, setActiveMilestone] = useState<CollaborationMilestone | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isPlansSectionHighlighted, setIsPlansSectionHighlighted] = useState(false);
  const [plansSectionY, setPlansSectionY] = useState<number | null>(null);
  const scrollViewRef = useRef<ScrollView | null>(null);
  const plansSectionHighlightTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const latestRequestIdRef = useRef(0);
  const latestGroupIdRef = useRef<string | null>(currentGroup?.id ?? null);

  const clearPlansSectionHighlightTimeout = useCallback(() => {
    if (plansSectionHighlightTimeoutRef.current) {
      clearTimeout(plansSectionHighlightTimeoutRef.current);
      plansSectionHighlightTimeoutRef.current = null;
    }
  }, []);

  useEffect(() => {
    latestGroupIdRef.current = currentGroup?.id ?? null;
  }, [currentGroup?.id]);

  useEffect(() => {
    clearPlansSectionHighlightTimeout();
    setIsPlansSectionHighlighted(false);
    setPlansSectionY(null);
  }, [clearPlansSectionHighlightTimeout, currentGroup?.id]);

  useEffect(
    () => () => {
      clearPlansSectionHighlightTimeout();
      latestRequestIdRef.current += 1;
    },
    [clearPlansSectionHighlightTimeout]
  );

  const loadWorkspace = useCallback(
    async (refresh = false) => {
      const groupId = currentGroup?.id ?? null;
      const groupKind = currentGroup?.groupKind;
      const requestId = latestRequestIdRef.current + 1;
      latestRequestIdRef.current = requestId;

      if (!groupId || !config) {
        setPlans([]);
        setPartyUnits([]);
        setConnectedFamilies([]);
        setPendingNetworkRequestCount(0);
        setIsLoading(false);
        setIsRefreshing(false);
        setError(null);
        return;
      }

      if (refresh) {
        setIsRefreshing(true);
      } else {
        setIsLoading(true);
      }

      try {
        let nextPlans: GroupPlan[] = [];
        let nextPartyUnits: GroupPartyUnit[] = [];
        let nextConnectedFamilies: ConnectedFamily[] = [];

        if (groupKind === 'META') {
          const [plansPayload, memberships, incomingInvites, adminInvites] = await Promise.all([
            groupsAPI.getPlans(groupId),
            familiesAPI.getMetaMemberships(),
            networkInvitesAPI.list({ scope: 'incoming' }),
            networkInvitesAPI.list({ scope: 'admin' }),
          ]);
          nextPlans = plansPayload;
          const homeFamilyId = currentFamily?.id ? String(currentFamily.id) : null;
          nextConnectedFamilies = memberships
            .filter((membership) => String(membership.meta_family?.id) === groupId)
            .map((membership) => membership.family)
            .filter(Boolean)
            .filter((family) => String(family.id) !== homeFamilyId)
            .map((family) => ({
              id: String(family.id),
              name: family.name,
              memberCount: family.members?.length,
            }))
            .sort((a, b) => a.name.localeCompare(b.name));
          setPendingNetworkRequestCount(
            [...incomingInvites, ...adminInvites].filter(
              (invite) => String(invite.meta_family?.id ?? '') === groupId
            ).length
          );
        } else {
          const [plansPayload, partyUnitsPayload] = await Promise.all([
            groupsAPI.getPlans(groupId),
            groupsAPI.getPartyUnits(groupId),
          ]);
          nextPlans = plansPayload;
          nextPartyUnits = partyUnitsPayload;
          setPendingNetworkRequestCount(0);
        }

        if (latestRequestIdRef.current !== requestId || latestGroupIdRef.current !== groupId) {
          return;
        }

        setPlans(nextPlans);
        setPartyUnits(nextPartyUnits);
        setConnectedFamilies(nextConnectedFamilies);
        setError(null);
      } catch (loadError) {
        if (latestRequestIdRef.current !== requestId || latestGroupIdRef.current !== groupId) {
          return;
        }
        console.error('Failed to load collaboration workspace:', loadError);
        setError('Failed to load collaboration plans.');
      } finally {
        if (latestRequestIdRef.current === requestId && latestGroupIdRef.current === groupId) {
          setIsLoading(false);
          setIsRefreshing(false);
        }
      }
    },
    [config, currentFamily?.id, currentGroup?.groupKind, currentGroup?.id]
  );

  useFocusEffect(
    useCallback(() => {
      let isFocused = true;

      const hydrateWorkspace = async () => {
        await loadWorkspace();
        if (!isFocused || !currentGroup?.id) {
          return;
        }

        const nextMilestone = takePendingWorkspaceMilestone(currentGroup.id);
