  const activeMilestoneMessage =
    activeMilestone && config ? (config.milestoneMessages[activeMilestone] ?? null) : null;

  const handleSetupAction = useCallback(() => {
    if (!setupStep || !currentGroup || !setupState) {
      return;
    }

    if (currentGroup.groupKind === 'META') {
      if (setupState === 'configured') {
        navigation.navigate('Trips', {
          screen: 'CreateTrip',
          params: {
            networkId: currentGroup.id,
            returnTo: 'detail',
          },
        });
        return;
      }

      navigation.navigate('InvitationScreen', {
        groupId: currentGroup.id,
      });
      return;
    }

    if (setupState === 'empty') {
      navigation.navigate('InvitationScreen', {
        groupId: currentGroup.id,
      });
      return;
    }

    if (setupState === 'invited') {
      navigation.navigate('GroupParticipants', {
        groupId: currentGroup.id,
      });
      return;
    }

    navigation.navigate('GroupPlanComposer', {
      groupId: currentGroup.id,
    });
  }, [currentGroup, navigation, setupState, setupStep]);

  if (!currentGroup || !config) {
    return null;
  }

  if (isLoading && !isRefreshing) {
    return (
      <SafeAreaView style={styles.loadingContainer}>
        <ActivityIndicator size="large" color={theme.colors.primary[400]} />
        <Text style={[styles.loadingText, { color: theme.colors.text.secondary }]}>
          Loading collaboration workspace...
        </Text>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView
      style={[styles.container, { backgroundColor: theme.colors.background.paper }]}
      testID="collaboration-workspace-screen"
    >
      <ScrollView
        ref={scrollViewRef}
        testID="collaboration-workspace-scroll"
        contentContainerStyle={styles.scrollContent}
        refreshControl={
          <RefreshControl refreshing={isRefreshing} onRefresh={() => void loadWorkspace(true)} />
        }
